def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    write_times = {}
    results = []
    current_time = 0

    def is_expired(key, t):
        if key not in write_times:
            return True
        return write_times[key] + ttl <= t

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            current_time = t

            # Remove expired entries that are in cache
            keys_to_remove = [k for k in cache if is_expired(k, t)]
            for k in keys_to_remove:
                del cache[k]
                del write_times[k]

            # If key already exists, remove it (we'll re-add it at the end)
            if key in cache:
                del cache[key]

            # If cache is at capacity, evict LRU entry
            if len(cache) >= capacity:
                lru_key, _ = cache.popitem(last=False)
                del write_times[lru_key]

            # Add the new entry
            cache[key] = value
            write_times[key] = t

        elif op[0] == 'get':
            _, t, key = op
            current_time = t

            # Check if key exists and is not expired
            if key in cache and not is_expired(key, t):
                results.append(cache[key])
                # Move to end (most recently used)
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results

